# Generated by .github/workflows/build.yml on each v* tag; edit the template
# in vukasin-nikodijevic/markdown-viewer, not the copy in the tap.
class MdViewer < Formula
  desc "Render Markdown files in a native window with GitHub styling"
  homepage "https://github.com/vukasin-nikodijevic/markdown-viewer"
  license "MIT"

  # Prebuilt binaries from the GitHub release: building from source on Linux
  # would pull in Homebrew's whole webkitgtk stack instead of the system one.
  on_macos do
    on_arm do
      url "https://github.com/vukasin-nikodijevic/markdown-viewer/releases/download/v0.1.3/md-viewer_0.1.3_darwin_arm64.tar.gz"
      sha256 "5bc7344023255a6cb5b8a78241ac9ef910128e0e0962fd646e8fd80d1027e88e"
    end
    on_intel do
      url "https://github.com/vukasin-nikodijevic/markdown-viewer/releases/download/v0.1.3/md-viewer_0.1.3_darwin_amd64.tar.gz"
      sha256 "4cee8c355ba70a967d97367888d9db4f23920502268653929e94498fa58fb237"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/vukasin-nikodijevic/markdown-viewer/releases/download/v0.1.3/md-viewer_0.1.3_linux_arm64.tar.gz"
      sha256 "8d68a994277b572cf5c8ed2d0babdf79ddda6fcf7464e96158252c42b4fd2009"
    end
    on_intel do
      url "https://github.com/vukasin-nikodijevic/markdown-viewer/releases/download/v0.1.3/md-viewer_0.1.3_linux_amd64.tar.gz"
      sha256 "555f3ff9c6c60915aa1395f38c4e553197d88d13eb4168e852ede7537f78e380"
    end
  end

  def install
    bin.install "md-viewer"
  end

  def caveats
    on_linux do
      <<~EOS
        md-viewer uses the system's GTK 3 and WebKitGTK 4.1. On Debian/Ubuntu:
          sudo apt install libgtk-3-0 libwebkit2gtk-4.1-0
      EOS
    end
  end

  test do
    # Must not open a GUI window; the usage error is enough
    assert_match "Usage", shell_output("#{bin}/md-viewer 2>&1", 1)
  end
end
